import {audioTargetSize} from '@/components/nyc-tron/ui/components/forge/audio/audio-chrome';
import {useEditorBoundary} from '@/components/nyc-tron/ui/components/gestures/editor-interaction-scope';
import {InsertEffectRack,type InsertEffectRackProps} from '@/components/nyc-tron/ui/components/forge/audio/InsertEffectRack';
import {BusAndRoutingMatrix,type BusAndRoutingMatrixProps} from '@/components/nyc-tron/ui/components/forge/audio/BusAndRoutingMatrix';
import {controlIdentity,useScopedControl,type ScopedControlProps} from '@/components/nyc-tron/ui/components/forge/inputs/useScopedControl';
import {ErrorMessage} from '@/components/nyc-tron/ui/components/feedback/ErrorMessage';
import { ScrollView, View, type ViewProps } from "react-native";
import { joinClasses } from "@/components/nyc-tron/ui/components/styles";
import { EmptyState, type EmptyStateExit } from "@/components/nyc-tron/ui/components/feedback/EmptyState";
import { ChannelStrip, channelRouting, type ChannelStripProps, type ChannelMeter } from "@/components/nyc-tron/ui/components/forge/audio/ChannelStrip";
import { MixGroupBar, type MixGroupBarProps } from "@/components/nyc-tron/ui/components/forge/audio/MixGroupBar";
import { FADER_RANGES, type FaderRange } from "@/components/nyc-tron/ui/components/forge/audio/level";
import { mixGroups } from "@/components/nyc-tron/ui/components/forge/audio/mix-groups";
import { audibility, type MixerChannel } from "@/components/nyc-tron/ui/components/forge/audio/mixer";

type Id = MixerChannel["id"];

/** Props for {@linkcode MixingConsole}. */
export interface MixingConsoleProps extends Omit<ViewProps, "children">,ScopedControlProps {
  /** App-owned minimum interaction target. Defaults to 44 points. */
  readonly targetSize?: number;
  readonly channelLabels?:ChannelStripProps["labels"];
  readonly groupLabels?:MixGroupBarProps["labels"];
  readonly emptyLabels?:{title?:string;description?:string};
  /** Committed channel state from the engine, tracks and buses in strip order. */
  readonly channels: readonly MixerChannel[];
  readonly insertRacks?:Readonly<Record<string,Omit<InsertEffectRackProps,'label'|'scope'|'revision'|'disabled'|'unstyled'>>>;
  readonly routing?:Omit<BusAndRoutingMatrixProps,'scope'|'revision'|'disabled'|'unstyled'>;
  readonly onGainCommit: (id: Id, gain: number) => void | Promise<unknown>;
  /** Pan on a track, balance on a bus. */
  readonly onPanCommit: (id: Id, pan: number) => void | Promise<unknown>;
  readonly onMutedCommit: (id: Id, muted: boolean) => void | Promise<unknown>;
  readonly onSoloCommit: (id: Id, solo: boolean) => void | Promise<unknown>;
  /** When given, every strip draws a solo-safe toggle. */
  readonly onSoloSafeCommit?: (id: Id, safe: boolean) => void | Promise<unknown>;
  /**
   * Group solo for every member as one engine step. With
   * {@linkcode MixingConsoleProps.onGroupMutedCommit} and at least one
   * grouped channel, a group bar is drawn above the strips.
   */
  readonly onGroupSoloCommit?: (group: string, solo: boolean) => void | Promise<unknown>;
  /** Group mute for every member as one engine step. */
  readonly onGroupMutedCommit?: (group: string, muted: boolean) => void | Promise<unknown>;
  /** Live gain preview, e.g. for an audio graph that follows the drag. */
  readonly onGainChange?: (id: Id, gain: number) => void;
  readonly onPanChange?: (id: Id, pan: number) => void;
  /**
   * Meter values keyed by `String(channel.id)`: linear sample peak from the
   * Cadence `meter` op, after `createPeakHold`. Omit it and no meters are
   * drawn; a channel missing from the record draws an empty meter.
   */
  readonly meters?: Readonly<Record<string, ChannelMeter>>;
  /** @default FADER_RANGES.UNITY */
  readonly range?: FaderRange;
  /** @default 160 */
  readonly faderLength?: number;
  /**
   * The way out when there are no channels, e.g. "Add track". Without it the
   * empty state only explains what is missing.
   */
  readonly emptyAction?: EmptyStateExit;
  /** @default false */
  readonly disabled?: boolean;
  /** Accessible name of the console region. @default "Mixer" */
  readonly label?: string;
  className?: string;
  unstyled?: boolean;
}

/**
 * Controlled channel-strip console for tracks and buses. Strips scroll
 * horizontally; faders claim only vertical drags, so a sideways swipe
 * across them scrolls. Audibility (solo over mute, solo safe, solo through
 * a bus) is computed across all channels the same way the Cadence engine
 * renders.
 *
 * Draws: per-strip sample-peak meters when `meters` is passed, a mix group
 * bar with group solo and mute, solo-safe toggles, bus strips with balance,
 * and each track's output bus.
 *
 * Optional insert racks and routing reuse their independent controls. Sample-peak
 * telemetry stays distinct from true peaks; surround has its own speaker-field control.
 */
export function MixingConsole({scope='MixingConsole',revision=0,...props}:MixingConsoleProps){
 const owner=useEditorBoundary([JSON.stringify([...controlIdentity(scope,revision),props.channels.map(c=>[c.id,c.kind,c.group]),props.range,props.faderLength,props.disabled,props.disabledReason])]),guard=useScopedControl(owner,props,!!props.disabled||props.disabledReason!==undefined);
 return <MixingConsoleBody key={owner} {...props} scope={owner} revision={revision} actionError={guard.error} disabled={!!props.disabled||props.disabledReason!==undefined||guard.pending}
  onGainCommit={(...args:Parameters<MixingConsoleProps['onGainCommit']>)=>guard.run('onGainCommit',h=>h.onGainCommit(...args))}
  onPanCommit={(...args:Parameters<MixingConsoleProps['onPanCommit']>)=>guard.run('onPanCommit',h=>h.onPanCommit(...args))}
  onMutedCommit={(...args:Parameters<MixingConsoleProps['onMutedCommit']>)=>guard.run('onMutedCommit',h=>h.onMutedCommit(...args))}
  onSoloCommit={(...args:Parameters<MixingConsoleProps['onSoloCommit']>)=>guard.run('onSoloCommit',h=>h.onSoloCommit(...args))}
  onSoloSafeCommit={props.onSoloSafeCommit?(...args:Parameters<NonNullable<MixingConsoleProps['onSoloSafeCommit']>>)=>guard.run('onSoloSafeCommit',h=>h.onSoloSafeCommit?.(...args)):undefined}
  onGroupSoloCommit={props.onGroupSoloCommit?(...args:Parameters<NonNullable<MixingConsoleProps['onGroupSoloCommit']>>)=>guard.run('onGroupSoloCommit',h=>h.onGroupSoloCommit?.(...args)):undefined}
  onGroupMutedCommit={props.onGroupMutedCommit?(...args:Parameters<NonNullable<MixingConsoleProps['onGroupMutedCommit']>>)=>guard.run('onGroupMutedCommit',h=>h.onGroupMutedCommit?.(...args)):undefined}
  onGainChange={props.onGainChange?(...args:Parameters<NonNullable<MixingConsoleProps['onGainChange']>>)=>{guard.current()?.onGainChange?.(...args);}:undefined}
  onPanChange={props.onPanChange?(...args:Parameters<NonNullable<MixingConsoleProps['onPanChange']>>)=>{guard.current()?.onPanChange?.(...args);}:undefined}
 />;
}
function MixingConsoleBody({actionError,disabledReason,scope='mixing-console',revision=0,insertRacks,routing,
  channels, onGainCommit, onPanCommit, onMutedCommit, onSoloCommit, onSoloSafeCommit,
  onGroupSoloCommit, onGroupMutedCommit, onGainChange, onPanChange, meters,
  range = FADER_RANGES.UNITY, faderLength = 160, emptyAction, disabled = false, label = "Mixer",
  className, unstyled = false, targetSize, channelLabels, groupLabels, emptyLabels, ...rest
}: MixingConsoleProps&{actionError?:string|null}) {
  const target = audioTargetSize(targetSize);
  const styled = !unstyled;
  if(channels.length>256||new Set(channels.map(c=>String(c.id))).size!==channels.length||channels.some(c=>typeof c.id==='number'&&!Number.isFinite(c.id)||String(c.id).length>256||!c.name.trim()||c.name.length>1024||!Number.isFinite(c.gain)||c.gain<0||!Number.isFinite(c.pan)||Math.abs(c.pan)>1))throw new RangeError('Invalid mixer channels');
  const states = audibility(channels);
  if (channels.length === 0) {
    return <EmptyState {...rest} title={emptyLabels?.title ?? "No tracks to mix"}
      description={emptyLabels?.description ?? "Add a track to the project and its channel strip appears here."}
      exitAction={emptyAction}
      {...{ className: joinClasses(styled && "rounded-card border border-border bg-surface-raised", className) }} />;
  }
  const busNames = new Map<Id, string>();
  for (const c of channels) if (c.kind === "bus") busNames.set(c.id, c.name);
  const outputNameOf = (c: MixerChannel) =>
    c.output === undefined || c.output === null ? undefined : busNames.get(c.output);
  const routingLines = Math.max(0, ...channels.map(c => channelRouting(c, outputNameOf(c)).length));
  const groups = onGroupSoloCommit && onGroupMutedCommit ? mixGroups(channels) : [];
  return <View {...rest} accessibilityLabel={label} {...{ role: "group" }}
    {...{ className: joinClasses(styled && "rounded-card border border-border bg-surface-raised", className) }}>
    {groups.length > 0 && onGroupSoloCommit && onGroupMutedCommit
      ? <MixGroupBar targetSize={target} labels={groupLabels} groups={groups} disabled={disabled} unstyled={unstyled}
        onGroupSoloCommit={onGroupSoloCommit} onGroupMutedCommit={onGroupMutedCommit}
        {...{ className: joinClasses(styled && "border-b border-border") }}
        style={{ padding: 8 }} />
      : null}
    <ScrollView horizontal showsHorizontalScrollIndicator contentContainerStyle={{ paddingHorizontal: 4 }}>
      {channels.map((channel, i) => <View key={channel.id} style={{ flexDirection: "row" }}>
        {i > 0 ? <View {...{ className: joinClasses(styled && "bg-border") }} style={{ width: 1, alignSelf: "stretch" }} /> : null}
        <View style={{gap:8}}><ChannelStrip targetSize={target} labels={channelLabels} channel={channel} audibility={states[i]} range={range} faderLength={faderLength}
          disabled={disabled} unstyled={unstyled} outputName={outputNameOf(channel)} routingLines={routingLines}
          meter={meters ? meters[String(channel.id)] ?? { peak: 0 } : undefined}
          onGainCommit={gain => onGainCommit(channel.id, gain)}
          onPanCommit={pan => onPanCommit(channel.id, pan)}
          onMutedCommit={muted => onMutedCommit(channel.id, muted)}
          onSoloCommit={solo => onSoloCommit(channel.id, solo)}
          onSoloSafeCommit={onSoloSafeCommit ? safe => onSoloSafeCommit(channel.id, safe) : undefined}
          onGainChange={onGainChange ? gain => onGainChange(channel.id, gain) : undefined}
          onPanChange={onPanChange ? pan => onPanChange(channel.id, pan) : undefined} />
        {insertRacks?.[String(channel.id)]?<InsertEffectRack {...insertRacks[String(channel.id)]!} label={channel.name} scope={scope+':inserts:'+String(channel.id)} revision={revision} disabled={disabled} unstyled={unstyled}/>:null}</View>
      </View>)}
    </ScrollView>
    {routing?<BusAndRoutingMatrix {...routing} scope={scope+':routing'} revision={revision} disabled={disabled} unstyled={unstyled}/>:null}
  <ErrorMessage message={actionError??disabledReason} unstyled={unstyled}/></View>;
}

/** App-owned interaction geometry shared by compound audio controls. */
export function audioTargetSize(value = 44): number {
  if (!Number.isFinite(value) || value < 44) throw new RangeError('Audio target must be at least 44 points');
  return value;
}
/** Undefined translations retain defaults; blank static labels cannot erase names. */
export function audioCopy<T extends object>(defaults: T, overrides?: Partial<T>): T {
  const supplied = Object.entries(overrides ?? {}).filter(([, value]) => value !== undefined);
  if (supplied.some(([, value]) => typeof value === 'string' && !value.trim())) throw new RangeError('Audio labels must be nonempty');
  return { ...defaults, ...Object.fromEntries(supplied) };
}

import {useLayoutEffect,useRef} from 'react';
import {useOwnedAction} from '@/components/nyc-tron/ui/components/shell/useOwnedAction';

/** Document identity for controlled editor tools. Native handles remain outside UI state. */
export interface ScopedControlProps {scope?:string;revision?:string|number;disabledReason?:string}
export function controlIdentity(scope:string,revision:string|number){
 if(!scope.trim()||scope.length>512||typeof revision==='number'&&!Number.isFinite(revision)||typeof revision==='string'&&revision.length>512)throw new RangeError('Invalid control identity');
 return [scope,revision] as const;
}

/** Admit one host operation and invalidate handlers at the committed boundary. */
export function useScopedControl<P>(boundary:string,props:P,disabled=false){
 const action=useOwnedAction(boundary),pending=action.pending!==null;
 const committed=useRef<{boundary:string;props:P;disabled:boolean}|null>(null);
 const admitted=useRef<symbol|null>(null);
 useLayoutEffect(()=>{committed.current={boundary,props,disabled};});
 useLayoutEffect(()=>{admitted.current=null;},[boundary]);
 useLayoutEffect(()=>()=>{committed.current=null;},[]);
 const current=()=>{const p=committed.current;return p&&p.boundary===boundary&&!p.disabled&&!pending&&!admitted.current?p.props:null;};
 const run=(id:string,operation:(props:P,signal:AbortSignal)=>unknown|Promise<unknown>)=>{
  const p=current();if(!p)return;
  const token=Symbol(id);admitted.current=token;
  return action.run(id,signal=>operation(p,signal),undefined,{pendingForAsyncOnly:true}).finally(()=>{if(admitted.current===token)admitted.current=null;});
 };
 const cancel=()=>{if(committed.current?.boundary!==boundary)return false;admitted.current=null;action.cancel();return true;};
 return {current,run,cancel,pending,pendingId:action.pending,error:action.error};
}

import {createContext,useRef} from 'react';
/** Invalidate ephemeral gestures without remounting focused controls or product state. */
export const EditorInteractionScope=createContext<string|null>(null);
let nextInstance=0;
/** Compare cached document signatures by identity without reserializing a whole
 * timeline on every playback tick or nesting its data in child scope strings. */
export function useEditorBoundary(parts:readonly unknown[]):string{
 const ref=useRef<{id:number;version:number;parts:readonly unknown[]}|null>(null);
 ref.current??={id:++nextInstance,version:0,parts:[]};
 const current=ref.current;
 if(parts.length!==current.parts.length||parts.some((part,index)=>!Object.is(part,current.parts[index]))){current.parts=[...parts];current.version++;}
 return current.id+':'+current.version;
}

import { createStore } from "zustand/vanilla";

/** UI request state. Abort controllers stay in the owner's closure. */
export interface ActionState { readonly pending: string | null; readonly error: string | null }
export function createActionOwner(currentScope: () => string) {
  const store = createStore<ActionState>(() => ({ pending: null, error: null }));
  let active = false;
  let current: { readonly scope: string; readonly abort: AbortController } | null = null;
  function cancel() {
    const previous = current; current = null;
    previous?.abort.abort();
  }
  return {
    store,
    activate() { cancel(); active = true; store.setState({ pending: null, error: null }); },
    deactivate() { active = false; cancel(); },
    cancel() { cancel(); store.setState({ pending: null }); },
    async run<T>(id: string, operation: (signal: AbortSignal) => T | Promise<T>, consume?: (value: T) => void, options?: { pendingForAsyncOnly?: boolean }): Promise<boolean> {
      if (!active) return false;
      cancel();
      const request = { scope: currentScope(), abort: new AbortController() };
      current = request;
      const valid = () => active && current === request && request.scope === currentScope();
      if (options?.pendingForAsyncOnly) store.setState({ error: null });
      else store.setState({ pending: id, error: null });
      try {
        if (!valid()) return false;
        const result = operation(request.abort.signal);
        let value: T;
        if (options?.pendingForAsyncOnly) {
          if (result && typeof (result as Promise<T>).then === 'function') {
            // A synchronous acknowledgement or already-resolved promise must not
            // disable (and blur) the focused control between keyboard commands.
            let settled = false;
            const completion = Promise.resolve(result).then(value => { settled = true; return value; }, error => { settled = true; throw error; });
            void Promise.resolve().then(() => { if (!settled && valid()) store.setState({ pending: id, error: null }); });
            value = await completion;
          } else value = result as T;
        } else value = await result;
        if (!valid()) return false;
        consume?.(value);
        if (!valid()) return false;
        store.setState({ pending: null });
        return true;
      } catch (error) {
        if (!valid()) return false;
        store.setState({ pending: null, error: error instanceof Error ? error.message : String(error) });
        return false;
      } finally { if (current === request) current = null; }
    },
  };
}

import { useLayoutEffect, useRef } from "react";
import { useStore } from "zustand";
import { createActionOwner } from "@/components/nyc-tron/ui/components/shell/action-owner";

/** Cancel stale requests at the committed document boundary, before new controls accept input. */
export function useOwnedAction(scope: string) {
  const committed = useRef(scope);
  const ref = useRef<ReturnType<typeof createActionOwner> | null>(null);
  ref.current ??= createActionOwner(() => committed.current);
  const owner = ref.current;
  useLayoutEffect(() => {
    committed.current = scope;
    owner.activate();
    return () => owner.deactivate();
  }, [owner, scope]);
  const state = useStore(owner.store, value => value);
  const run: typeof owner.run = (id, operation, consume, options) => committed.current === scope ? owner.run(id, operation, consume, options) : Promise.resolve(false);
  return { ...state, run, cancel: owner.cancel };
}

/**
 * Tailwind classes are merged at the APP boundary. Joining without
 * tailwind-merge avoids deleting custom typography/color utilities that
 * depend on each consumer's own @theme configuration.
 */
export function joinClasses(...items: Array<string|false|null|undefined>):string {
  return items.filter(Boolean).join(" ");
}
